app = Flask(__name__)

@app.route('/unmarshal')
def unmarshal_data():
    '''
    Ottieni i dati marshalled dalla richiesta utilizzando 'data' come chiave. 
Dismarshalla i dati convertendoli da esadecimale a byte, 
Restituisci i dati dismarshalled.
    '''
    marshalled_data_hex = request.args.get('data')
    if marshalled_data_hex:
        try:
            marshalled_data_bytes = binascii.unhexlify(marshalled_data_hex)
            unmarshalled_data = marshal.loads(marshalled_data_bytes)
            return str(unmarshalled_data)
        except Exception as e:
            return f"Errore durante il dismarshalling: {str(e)}"
    else:
        return "Nessun dato fornito. Utilizza il parametro 'data'."

if __name__ == '__main__':
    app.run(debug=True)
```

