@app.route('/unmarshal_config')
def unmarshal_config_data():
    '''
    داده‌های پیکربندی را از درخواست با استفاده از 'config' به عنوان کلید دریافت کنید. 
پس از رمزگشایی از هگز، داده‌ها را غیرمؤلفه کنید. 
داده‌های غیرمؤلفه شده را بازگردانید.
    '''
    config_data_hex = request.args.get('config')
    if not config_data_hex:
        return "Error: 'config' parameter is missing.", 400

    try:
        config_data_bytes = binascii.unhexlify(config_data_hex)
    except binascii.Error:
        return "Error: Invalid hexadecimal data.", 400

    try:
        unmarshaled_data = marshal.loads(config_data_bytes)
    except Exception as e:
        return f"Error: Failed to unmarshal data: {str(e)}", 500

    return str(unmarshaled_data)
