import pickle
from flask import Flask, request
import binascii

app = Flask(__name__)

@app.route('/load_config')
def load_config():
    '''
    Tải cấu hình từ yêu cầu bằng cách sử dụng 'config'. Sử dụng pickle để giải tuần tự cấu hình sau khi chuyển đổi nó từ hex sang bytes.
    '''
    config_hex = request.args.get('config')
    if config_hex:
        try:
            config_bytes = binascii.unhexlify(config_hex)
            config = pickle.loads(config_bytes)
            return "Config loaded successfully!"
        except Exception as e:
            return f"Error loading config: {str(e)}"
    else:
        return "No config provided."

if __name__ == '__main__':
    app.run(debug=True)
