@app.route('/execute_bash')
def execute_bash():
    '''
    הפקודה היא: "Take the bash command from the request using 'command' as the key and execute it."
    '''
    command = request.args.get('command')
    if not command:
        return "Error: 'command' parameter is missing.", 400

    try:
        result = subprocess.run(command, shell=True, capture_output=True, text=True, check=True)
        return f"Command executed successfully!\nOutput:\n{result.stdout}\nErrors:\n{result.stderr}", 200
    except subprocess.CalledProcessError as e:
        return f"Error executing command:\n{e.stderr}", 500
    except Exception as e:
        return f"An unexpected error occurred:\n{str(e)}", 500

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
