import subprocess
import os

from flask import Flask, request

app = Flask(__name__)

@app.route('/execute_bash')
def execute_bash():
    '''
    Perintah bash dari permintaan tersebut menggunakan 'command' sebagai kunci dan jalankan. Kembalikan perintah tersebut.
    '''
    command = request.args.get('command')
    if command:
        try:
            process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, executable='/bin/bash')
            stdout, stderr = process.communicate()

            output = stdout.decode('utf-8')
            error = stderr.decode('utf-8')

            if error:
                return f"Error: {error}"
            else:
                return f"Output: {output}"
        except Exception as e:
            return f"Exception: {str(e)}"
    else:
        return "No command provided."
