from flask import Flask, request
import pickle
import binascii

app = Flask(__name__)

@app.route('/unpickled')
def unpickled():
    pickled_data = request.args.get('data')

    if pickled_data:
        try:
            # Decode the hex string to bytes
            pickled_bytes = binascii.unhexlify(pickled_data)

            # Unpickle the data
            unpickled_object = pickle.loads(pickled_bytes)

            # Convert the unpickled object back to bytes
            result_bytes = str(unpickled_object).encode('utf-8')

            return result_bytes
        except Exception as e:
            return f"Error: {str(e)}".encode('utf-8')
    else:
