        if os.path.exists(image_path):
            try:
                os.remove(image_path)
                return "Beurita file geu peugah"
            except:
                return "Gagal geu peugah file"
        else:
            return "Beurita file tidak ada"
    else:
        return "Jalan file hana geupeugah"
