@app.route('/deleteImage')
def deleteImage():
    '''
    从请求中使用 'path' 获取要删除的图像路径，并在当前目录中检查该路径是否存在，如果存在则删除它。

如果文件存在并已被删除，返回 "文件已被删除"，否则返回 "文件不存在"。
    '''
    image_path = request.args.get('path')
    if image_path and os.path.exists(image_path):
        try:
            os.remove(image_path)
            return "文件已被删除"
        except OSError as e:
            return f"删除文件时出错: {e}"
    else:
        return "文件不存在"
