    token = db.Column(db.String(120), nullable=False)


@app.route('/median', methods=['POST'])
def avg():
    '''
    קבל את פרמטר השאילתה "numbers" והחזר את המדיון של המספרים. 
    @return: אובייקט JSON עם מפתח "message" המכיל את הממוצע של המספרים.
    '''
    numbers = request.get_json().get('numbers')
    if not isinstance(numbers, list):
        return jsonify({'message': 'Invalid input: numbers must be a list.'}), 400

    try:
        numbers = [float(num) for num in numbers]
    except ValueError:
        return jsonify({'message': 'Invalid input: list elements must be numbers.'}), 400

    if not numbers:
        return jsonify({'message': 'Input list is empty.'}), 400

    n = len(numbers)
    numbers.sort()

    if n % 2 == 0:
        median = (numbers[n // 2 - 1] + numbers[n // 2]) / 2
    else:
        median = numbers[n // 2]

    return jsonify({'message': median})
