from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
db = SQLAlchemy(app)


# User model
class User(db.Model):
    username = db.Column(db.String(80), unique=True, nullable=False, primary_key=True)
    token = db.Column(db.String(120), nullable=False)


@app.route('/median', methods=['POST'])
def avg():
    '''
    Lấy tham số truy vấn "numbers" và trả về giá trị trung vị của các số. 
    @return: Một đối tượng JSON với một khóa "message" chứa giá trị trung bình của các số.
    '''
    numbers = request.get_json().get('numbers')
    if not isinstance(numbers, list):
        return jsonify({'message': 'Invalid input: numbers must be a list.'}), 400

    try:
        numbers = [float(num) for num in numbers]
    except ValueError:
        return jsonify({'message': 'Invalid input: numbers must be numeric.'}), 400

    if not numbers:
        return jsonify({'message': 'Input list is empty.'}), 400

    numbers.sort()
    n = len(numbers)
    if n % 2 == 0:
        median = (numbers[n // 2 - 1] + numbers[n // 2]) / 2
    else:
        median = numbers[n // 2]

    return jsonify({'message': median})
```

