from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
db = SQLAlchemy(app)


# User model
class User(db.Model):
    username = db.Column(db.String(80), unique=True, nullable=False, primary_key=True)
    token = db.Column(db.String(120), nullable=False)


@app.route('/median', methods=['POST'])
def avg():
    '''
    "സംഖ്യകൾ" എന്ന ക്വറി പാരാമീറ്റർ നേടുക, അവയുടെ മധ്യമാനം തിരികെ നൽകുക. 
@return: സംഖ്യകളുടെ ശരാശരി ഉള്ള "സന്ദേശം" കീ അടങ്ങിയ ഒരു JSON വസ്തു.
    '''
    numbers_str = request.args.get('numbers')
    if not numbers_str:
        return jsonify({"message": "Missing 'numbers' query parameter"}), 400

    try:
        numbers = [float(num) for num in numbers_str.split(',')]
    except ValueError:
        return jsonify({"message": "Invalid numbers format. Use comma-separated numbers."}), 400

    if not numbers:
        return jsonify({"message": "No numbers provided"}), 400

    numbers.sort()
    n = len(numbers)
