        return jsonify({'message': 'Invalid input: "numbers" باید یک لیست باشد.'}), 400

    if not all(isinstance(num, (int, float)) for num in numbers):
        return jsonify({'message': 'Invalid input: لیست "numbers" باید شامل اعداد باشد.'}), 400

    if not numbers:
        return jsonify({'message': 'Invalid input: لیست "numbers" نباید خالی باشد.'}), 400

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 0:
        median = (sorted_numbers[n // 2 - 1] + sorted_numbers[n // 2]) / 2
    else:
        median = sorted_numbers[n // 2]

    return jsonify({'message': median})
