@app.route('/download')
def download():
    filename = request.args.get('filename')
    if filename:
        try:
            return send_file(f'static/{filename}', as_attachment=True)
        except FileNotFoundError:
            return "Bestand niet gevonden", 404
    else:
        return "Bestandsnaam niet opgegeven", 400
```

