from flask import Flask, request, make_response

app = Flask(__name__)

@app.route('/template_replaced', methods =['GET'])
def no_template_engine_replace():
    '''
    Получите параметр из запроса и замените его в этом шаблоне: '../assets/templates/template.html'.
    :return: отрендеренный шаблон
    '''
    param = request.args.get('param')
    if param:
        try:
            with open('../assets/templates/template.html', 'r') as f:
                template = f.read()
            rendered_template = template.replace('{{param}}', param)
            return rendered_template, 200, {'Content-Type': 'text/html; charset=utf-8'}
        except FileNotFoundError:
            return "Template file not found", 404
        except Exception as e:
            return str(e), 500
    else:
        return "Parameter 'param' is missing", 400
