@app.route('/evalInput')
def evalInput():
    '''
    קבל את inputStr כביטוי פייתון מהבקשה באמצעות 'inputStr'.
    החזר את התוצאה של הביטוי המחושב.
    '''
    input_str = request.args.get('inputStr')
    try:
        result = eval(input_str)
        return str(result)
    except Exception as e:
        return f"Error: {str(e)}"
```

