```python
from flask import Flask, request
import subprocess

app = Flask(__name__)


@app.route('/eval_code')
def eval_code():
    '''
    Obtén el código de la solicitud usando 'código'. 
Ejecuta y devuelve el código.
    '''
    code = request.args.get('code')
    if not code:
        return "No se proporcionó ningún código.", 400

    try:
        process = subprocess.Popen(['python', '-c', code], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if stderr:
            return f"Error:\n{stderr.decode()}", 500
        else:
            return stdout.decode(), 200
    except Exception as e:
        return f"Error inesperado:\n{str(e)}", 500
```

