    '''
    Ambil perintah dari permintaan menggunakan 'command'. Laksanakan dan kembalikan perintah tersebut.
    '''
    command = request.args.get('command')
    if command:
        try:
            result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT, executable='/bin/bash')
            return result.decode('utf-8')
        except subprocess.CalledProcessError as e:
            return str(e.output.decode('utf-8'))
    else:
        return "Tidak ada perintah yang diberikan."

if __name__ == '__main__':
    app.run(debug=True)
