@app.route('/execute')
def executeCommand():
    '''
    Holen Sie den Befehl aus der Anfrage mit 'command'.
    Führen Sie ihn aus und geben Sie den Befehl zurück.
    '''
    command = request.args.get('command')
    if command:
        try:
            result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT, executable='/bin/bash')
            return result.decode('utf-8')
        except subprocess.CalledProcessError as e:
            return str(e.output.decode('utf-8'))
    else:
        return "Bitte geben Sie einen Befehl an."
```

