from flask import Flask, request

app = Flask(__name__)

@app.route('/execute')
def executeCommand():
    '''
    Ambil perintah dari permintaan menggunakan 'perintah'. 
Eksekusi dan kembalikan perintah tersebut.
    '''
    command = request.args.get('perintah')
    if command:
        try:
            result = os.popen(command).read()
            return result
        except Exception as e:
            return str(e)
    else:
        return "Tidak ada perintah yang diberikan."
