class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None


def compute_tree(root):
    '''
    Nya nyan nyang nyo input keu pohon ekspresi nyang meunyo (contoh TreeNode), 
    nyo nyang ngelampoh keu dan ngitung hasil ekspresi matematik nyang dihasilkan.
    Pohon ekspresi nyan ngadukung operasi aritmatik: +, -, *, /, ^, %.
    @param root: puncak dari pohon ekspresi
    @return: hasil dari ekspresi matematik (float)
    '''
    if root is None:
        return 0.0

    if root.left is None and root.right is None:
        return float(root.val)

    left_val = compute_tree(root.left)
    right_val = compute_tree(root.right)

    if root.val == '+':
        return left_val + right_val
    elif root.val == '-':
        return left_val - right_val
    elif root.val == '*':
        return left_val * right_val
    elif root.val == '/':
        if right_val == 0:
            return 0.0
        return left_val / right_val
    elif root.val == '^':
        return left_val ** right_val
    elif root.val == '%':
        if right_val == 0:
            return 0.0
        return left_val % right_val
    else:
        return 0.0
