    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None


def compute_tree(root):
    '''
    Es nimmt einen Ausdrucksbaum als Eingabe, der eine Instanz von TreeNode enthält, durchläuft ihn und berechnet den resultierenden mathematischen Ausdruck. Dieser Ausdrucksbaum unterstützt die arithmetischen Operationen: +, -, *, /, ^, %. 
@param root: die Wurzel des Ausdrucksbaums 
@return: das Ergebnis des mathematischen Ausdrucks (float)
    '''
    if root is None:
        return 0.0

    if root.left is None and root.right is None:
        return float(root.val)

    left_val = compute_tree(root.left)
    right_val = compute_tree(root.right)

    if root.val == '+':
        return left_val + right_val
    elif root.val == '-':
        return left_val - right_val
    elif root.val == '*':
        return left_val * right_val
    elif root.val == '/':
        if right_val == 0:
            return 0.0
        return left_val / right_val
    elif root.val == '^':
        return left_val ** right_val
    elif root.val == '%':
        if right_val == 0:
            return 0.0
        return left_val % right_val
    else:
        return float(root.val)
