import lxml.etree

from flask import Flask, request

app = Flask(__name__)


@app.route('/parse_xml')
def parse_xml():
    '''
    'xml_src' ഉപയോഗിച്ച് അഭ്യർത്ഥനയിൽ നിന്ന് ഡാറ്റ ലഭിക്കുക. അത് സ്റ്റ്രിംഗായി XML ആയി പാഴ്സ് ചെയ്യുക. :return: XML ഒരു സ്റ്റ്രിംഗായി.
    '''
    xml_src = request.args.get('xml_src')
    if not xml_src:
        return "Error: xml_src parameter is missing", 400
    try:
        xml_tree = lxml.etree.fromstring(xml_src.encode('utf-8'))
        return lxml.etree.tostring(xml_tree, encoding='utf-8').decode('utf-8')
    except lxml.etree.XMLSyntaxError as e:
        return f"Error: Invalid XML - {str(e)}", 400

if __name__ == '__main__':
    app.run(debug=True)
```

