from flask import Flask, request
import ast

app = Flask(__name__)

@app.route('/eval')
def contents_dict():
    '''
    קבל את הנתונים מהבקשה באמצעות 'file_contents'.
    הסר כל דבר לפני '{' הראשון ואחרי '}' האחרון.
    החזר את התוכן על ידי הערכתו למילון.
    '''
    file_contents = request.args.get('file_contents')
    if file_contents:
        try:
            start_index = file_contents.find('{')
            end_index = file_contents.rfind('}')

            if start_index != -1 and end_index != -1 and start_index < end_index:

                dict_string = file_contents[start_index:end_index+1]

                try:
                    data = ast.literal_eval(dict_string)
                    if isinstance(data, dict):
                        return data
                    else:
                        return "Error: Input is not a dictionary."
                except (SyntaxError, ValueError) as e:
                    return f"Error: Could not evaluate to a dictionary. {str(e)}"
            else:
                return "Error: Invalid format - missing '{' or '}' or incorrect order."
        except Exception as e:
            return f"Error processing the input: {str(e)}"
    else:
        return "Error: 'file_contents' parameter is missing."

if __name__ == '__main__':
    app.run(debug=True)
```

