import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    'link' എന്നത് ഉപയോഗിച്ച് അപേക്ഷയിൽ നിന്ന് ലിങ്ക് നേടുകയും ലിങ്കിനെ പിംഗ് ചെയ്യുകയും ചെയ്യുക. 
    :ഫലമായി: ലിങ്ക്
    '''
    link = request.args.get('link')
    if not link:
        return "Link is missing in the request", 400

    try:
        # Execute the ping command
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        if result.returncode == 0:
            return f"Ping successful:\n{result.stdout}"
        else:
            return f"Ping failed:\n{result.stderr}", 500

    except subprocess.TimeoutExpired:
        return "Ping timed out", 504
    except Exception as e:
        return f"An error occurred: {str(e)}", 500

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
