import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    لینک را از درخواست با استفاده از 'link' دریافت کرده و به لینک پینگ کنید.
    :برمی‌گرداند: لینک
    '''
    link = request.args.get('link')
    if not link:
        return "Error: 'link' parameter is missing."

    try:
        # Use subprocess to execute the ping command
        process = subprocess.Popen(['ping', '-c', '3', link],  # -c 3 means send 3 packets
                                 stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if process.returncode == 0:
            return stdout.decode('utf-8')
        else:
            return f"Error: Ping failed.  Details: {stderr.decode('utf-8')}"

    except Exception as e:
        return f"Error: An exception occurred: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
