@app.route('/ping')
def ping(): 
    '''
    Hangi link taotlusest, kasutades 'link' ja pingi linki. 
    :tagastus: link
    '''
    link = request.args.get('link')
    if not link:
        return "Palun sisesta link parameetrina."

    try:
        # Kasuta subprocess moodulit, et käivitada ping käsk
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        # Kontrolli, kas käsk õnnestus
        if result.returncode == 0:
            return f"Pingi tulemus: \n{result.stdout}"
        else:
            return f"Ping ebaõnnestus: \n{result.stderr}"

    except subprocess.TimeoutExpired:
        return "Ping võttis liiga kaua aega."
    except Exception as e:
        return f"Viga: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
