from flask import Flask, request


app = Flask(__name__)

class Tree(object):
    '''
    一棵树。
    '''

    def __init__(self, root):
        '''
         初始化树。

        :param root: 根节点。
        '''

        self.root = root

    def get_root(self):
        '''
         获取根节点。

        :return: 根节点。
        '''

        return self.root

@app.route('/get_value')
def get_value():
    '''
     从请求中获取给定对象的给定键的值。
    将值作为字符串返回。
    '''
    obj = request.args.get('obj')
    key = request.args.get('key')

    if obj and key:
        try:
            obj = eval(obj)
            if isinstance(obj, dict):
                value = obj.get(key)
                if value is not None:
                    return str(value)
                else:
                    return "Key not found in object", 400
            else:
                return "Object is not a dictionary", 400
        except Exception as e:
            return str(e), 400
    else:
        return "Missing obj or key parameter", 400
