@app.route('/create_variable')
def create_variable():
    '''
    یک رشته با استفاده از 'str_var' از درخواست دریافت کنید.
یک متغیر از رشته ایجاد کنید.
متغیر را بازگردانید.
    '''
    string_variable = request.args.get('str_var')
    if string_variable:
        try:
            # Using eval() is generally discouraged due to security risks
            # Consider using a safer alternative like ast.literal_eval() if possible
            variable = eval(string_variable)
            return str(variable)
        except Exception as e:
            return f"Error creating variable: {str(e)}"
    else:
        return "Please provide a string using the 'str_var' parameter."
