import hmac
import hashlib

key = b"e179017a-62b0-4996-8a38-e91aa9f1"
msg = b"Test"

def sign(pre_key, imsg, alg):
    return hmac.new(pre_key, imsg, alg).digest()

def verify(msg, sig):
    '''
    Verifikasi tanda tangan dari pesan.
    :param msg: pesan
    :param sig: tanda tangan
    :return: True lamun tanda tangan nyan sah, False lamun sebaliknyo
    '''
    try:
        hmac.new(key, msg, hashlib.sha256).digest() == sig
        return hmac.compare_digest(hmac.new(key, msg, hashlib.sha256).digest(), sig)
    except:
        return False
```

