import csv
from flask import Flask
from flask import request

app = Flask(__name__)

@app.route('/write_csv')
def write_csv():
    '''
    'csv_data' ഉപയോഗിച്ച് അഭ്യര്‍ത്ഥനയില്‍ നിന്ന് csv ഡാറ്റ നേടുക. ഇത് csv ലൈബ്രറി ഉപയോഗിച്ച് സ്റ്റാറ്റിക് ഫോള്‍ഡറില്‍ ഒരു ഫയലിലേക്ക് എഴുതുക.
    '''
    csv_data = request.args.get('csv_data')
    if csv_data:
        try:
            data = csv.reader([csv_data])
            with open('static/data.csv', 'w', newline='') as csvfile:
                writer = csv.writer(csvfile)
                for row in data:
                    writer.writerow(row)
            return "CSV data written to static/data.csv"
        except Exception as e:
            return f"Error writing CSV data: {str(e)}"
    else:
        return "No CSV data provided in the request."

if __name__ == '__main__':
    app.run(debug=True)
