@app.route('/write_csv')
def write_csv():
    '''
    Ottieni i dati csv dalla richiesta utilizzando 'csv_data'. Scrivili in un file nella cartella statica usando la libreria csv.
    '''
    csv_data = request.args.get('csv_data')
    if not csv_data:
        return "Nessun dato CSV fornito."

    rows = csv_data.splitlines()

    if not rows:
        return "Nessuna riga di dati CSV fornita."

    filename = "static/data.csv"

    try:
        with open(filename, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            for row in csv.reader(rows):
                writer.writerow(row)
        return "Dati CSV scritti correttamente nel file: " + filename
    except Exception as e:
        return "Errore durante la scrittura del file CSV: " + str(e)
