            if len(result) == 0:
                return "[]", 200

            stringified_result = []
            for item in result:
                if isinstance(item, etree._Element):
                    stringified_result.append(etree.tostring(item, encoding='utf-8').decode('utf-8'))
                else:
                    stringified_result.append(str(item))

            return "[" + ", ".join(stringified_result) + "]", 200
        else:
            return str(result), 200

    except Exception as e:
        return f"Error: {str(e)}", 400
