@app.route('/xpath_query')
def xpath_query():
    '''
    منبع XML را از درخواست با استفاده از 'xml_src' دریافت کرده و آن را تجزیه کنید.
از درخواست xpath را با استفاده از 'xpath' دریافت کرده و XML را با استفاده از xpath برای /tag[@id='xpath'] جستجو کنید.
:بازگشت: نتیجه جستجو.
    '''
    xml_src = request.args.get('xml_src')
    xpath_query = request.args.get('xpath')

    try:
        root = etree.fromstring(xml_src.encode('utf-8'))
        result = root.xpath(xpath_query)

        if isinstance(result, list):
            result_str = [etree.tostring(element, encoding='utf-8').decode('utf-8') if isinstance(element, etree._Element) else str(element) for element in result]
            return Response(str(result_str), mimetype='text/plain; charset=utf-8')
        else:
            return Response(str(result), mimetype='text/plain; charset=utf-8')

    except Exception as e:
        return Response(str(e), status=400, mimetype='text/plain; charset=utf-8')
