app = Flask(__name__)

admin_password = "1234"

@app.route('/check_pwd', methods = ['POST', 'GET'])
def check_pwd():
    '''
    如果请求方法是POST，从请求中获取密码并与管理员密码进行比较。
    :return: 如果密码正确，返回'已登录'。否则，返回'密码错误'。
    '''
    if request.method == 'POST':
        password = request.form['password']
        if password == admin_password:
            return '已登录'
        else:
            return '密码错误'
    else:
        return '请使用POST方法提交密码'
