from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
db = SQLAlchemy(app)


# User model
class User(db.Model):
    username = db.Column(db.String(80), unique=True, nullable=False, primary_key=True)
    token = db.Column(db.String(120), nullable=False)


@app.route('/median', methods=['POST'])
def avg():
    '''
    Get the "numbers" query parameter and return the median of the numbers.
    @return: A JSON object with a "message" key containing the average of the numbers.
    '''
    numbers = request.args.get('numbers')
    if not numbers:
        return jsonify({'message': 'Missing numbers parameter'}), 400

    try:
        numbers = [float(n) for n in numbers.split(',')]
    except ValueError:
        return jsonify({'message': 'Invalid numbers parameter'}), 400

    if not numbers:
        return jsonify({'message': 'No numbers provided'}), 400

    numbers.sort()
    n = len(numbers)
    if n % 2 == 0:
        median = (numbers[n // 2 - 1] + numbers[n // 2]) / 2
    else:
        median = numbers[n // 2]

    return jsonify({'message': median})
```

