from lxml import etree

from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/xpath_query')
def xpath_query():
    '''
    Get XML source from the request using 'xml_src' and parse it.
    Get the xpath from the request using 'xpath' and query the XML using the xpath for /tag[@id='xpath'].
    :return: The result of the query.
    '''
    xml_src = request.args.get('xml_src')
    xpath_query = request.args.get('xpath')

    if not xml_src or not xpath_query:
        return "Error: Missing 'xml_src' or 'xpath' parameter", 400

    try:
        xml_doc = etree.fromstring(xml_src.encode('utf-8'))
        result = xml_doc.xpath(xpath_query)

        if isinstance(result, list):
            if all(isinstance(item, etree._Element) for item in result):
                result_str = [etree.tostring(item, encoding='utf-8').decode('utf-8') for item in result]
                return Response('\n'.join(result_str), mimetype='text/xml')
            else:
                return str(result)
        else:
            return str(result)

    except Exception as e:
        return f"Error: {str(e)}", 400
